#!/usr/bin/env python3
"""Try to decrypt FMX cmd files with etc/key/aes_key.bin using various AES modes/offsets."""
import sys, struct, itertools
from Crypto.Cipher import AES

key = open(r'C:\zyh\work\宇树固件\real_unitree_r1_1.4.2\etc\key\aes_key.bin','rb').read()
print('key:', key.hex(), 'len', len(key))

path = sys.argv[1]
data = open(path,'rb').read()
print('file len', len(data), 'head:', data[:12].hex())
assert data[:3] == b'FMX'
ver = data[3]
crc = data[4:8]
plen, = struct.unpack_from('<I', data, 8)
print('ver', ver, 'crc', crc.hex(), 'plen', plen)
body = data[12:]

def score(b):
    return sum(1 for c in b if 32 <= c < 127 or c in (9,10,13))

# try ECB on body (if multiple of 16)
for off in range(0, 24):
    chunk = data[off:]
    if len(chunk) >= 16 and len(chunk) % 16 == 0:
        dec = AES.new(key, AES.MODE_ECB).decrypt(chunk)
        s = score(dec)
        print(f'ECB off={off} len={len(chunk)} score={s}/{len(dec)}', dec[:60] if s > len(dec)*0.7 else '')
# try CBC with IV = key, zero IV, iv=first16 of body at offsets
for ivname, iv in [('zero', b'\0'*16), ('key', key), ('crc+', crc + b'\0'*12)]:
    for off in (4, 8, 12, 16, 20, 24, 28):
        chunk = data[off:]
        if len(chunk) >= 16 and len(chunk) % 16 == 0:
            try:
                dec = AES.new(key, AES.MODE_CBC, iv).decrypt(chunk)
                s = score(dec)
                if s > len(dec)*0.6:
                    print(f'CBC iv={ivname} off={off} score={s}/{len(dec)}', dec[:80])
            except Exception as e: pass
# try CTR with various nonces
for off in (12, 16, 20, 28):
    chunk = data[off:]
    for nonce_off in (4, 8, 12):
        nonce = data[nonce_off:nonce_off+8]
        iv = data[nonce_off:nonce_off+16]
        try:
            dec = AES.new(key, AES.MODE_CTR, nonce=nonce, initial_value=0).decrypt(chunk)
            s = score(dec)
            if len(dec) and s > len(dec)*0.7:
                print(f'CTR nonce@{nonce_off} off={off} score={s}/{len(dec)}', dec[:80])
            dec = AES.new(key, AES.MODE_CFB, iv=iv, segment_size=128).decrypt(chunk)
            s = score(dec)
            if len(dec) and s > len(dec)*0.7:
                print(f'CFB iv@{nonce_off} off={off} score={s}/{len(dec)}', dec[:80])
        except Exception:
            pass
# try CBC ciphertext stealing not supported; try ECB on body minus trailing bytes
for trail in range(0, 16):
    chunk = body[:len(body)-trail] if trail else body
    if len(chunk) >= 16 and len(chunk) % 16 == 0:
        dec = AES.new(key, AES.MODE_ECB).decrypt(chunk)
        s = score(dec)
        if s > len(dec)*0.6:
            print(f'ECB body trail={trail} score={s}/{len(dec)}', dec[:80])

